content('الكاليسثنيكس', ['قوة بوزن الجسم. تحكّم بالحركة. تقدّم مستدام.', 'دليل شامل: من الأساسيات إلى المهارات المتقدمة', 'إعداد وتقديم: [اسم مقدم العرض]', 'عرض تعليمي للبالغين | 20–25 دقيقة'], 'صورة واقعية لرياضي يؤدي تمرين الضغط على قضبان متوازية، مع مساحة داكنة للعنوان.', 'تركيب تحريري: صورة نصفية وثلاث كلمات محورية.', 'ابدأ بسؤال: هل يحتاج بناء القوة إلى أجهزة كثيرة؟ قدّم الكاليسثنيكس بوصفه تدريب مقاومة يعتمد أساسًا على وزن الجسم، وليس مجرد حركات استعراضية. يربط العرض بين فهم الحركة، اختيار مستوى مناسب، بناء خطة، وقياس التحسن. المحتوى تثقيفي عام للبالغين الأصحاء، وليس وصفة علاجية أو برنامجًا فرديًا. استبدل حقل الاسم باسم مقدم العرض قبل التقديم. امنح العرض نحو عشرين إلى خمس وعشرين دقيقة مع وقت إضافي للنقاش.')
content('من تمارين بسيطة إلى رياضة متكاملة', ['جذور في التمارين البدنية والجمباز؛ حضور معاصر في الحدائق والصالات.', 'الأساسيات: تكرارات متحكَّم بها لبناء القوة والتحمّل.', 'الثبات والمهارات: توازن وتحكّم عصبي عضلي.', 'الأسلوب الحر (Freestyle): حركات ديناميكية متقدمة.'], 'صورة تدريب على العقلة في الهواء الطلق.', 'ثلاث بطاقات تصنيف: الأساسيات ← الثبات ← الأسلوب الحر؛ تصنيف لا تسلسل إلزامي.', 'اشرح أن المصطلح يرتبط لغويًا بالجمال والقوة، وأن تمارين وزن الجسم أقدم من انتشار رياضة الشارع الحديثة. لا تعني الكاليسثنيكس التدريب خارج الصالة حصرًا؛ يمكن ممارستها في المنزل أو النادي. تتقاطع مع الجمباز وتمارين الشارع، لكنها ليست مرادفًا لكل منهما. بعض الممارسين يركزون على التكرارات، وبعضهم على الثبات، وغيرهم على الأداء الديناميكي. لا يحتاج المبتدئ إلى الأسلوب الحر ليحصل على فوائد تدريبية، والصورة توضيحية وليست تعليمًا تقنيًا كاملاً.', [STUDY])
content('افهم الحمل قبل أن تزيد الصعوبة', ['وزن الجسم هو المقاومة الأساسية؛ الرافعة تغيّر الحمل.', 'المجموعة (Set): سلسلة تكرارات؛ التكرار (Rep): حركة كاملة.', 'المدى الحركي (ROM): مسافة حركة قابلة للتحكّم.', 'الحمل التدريجي (Progressive Overload): زيادة مدروسة للمطلب.', 'تكرارات احتياطية (RIR): ما تستطيع أداءه قبل العجز.'], 'رسم متدرج لنسخ تمرين الضغط بدل صور متشابهة.', 'سُلّم تقدم قابل للتحرير: ضغط على الحائط ← سطح مرتفع ← الأرض ← رفع القدمين.', 'بيّن أن تمرين وزن الجسم ليس ذا حمل ثابت عمليًا؛ زاوية الجسم وطول الرافعة ونقاط الارتكاز تغيّر صعوبته. التكرار الجيد يحافظ على السيطرة ضمن مدى مناسب دون ألم. إذا أمكن أداء نسختك بسهولة مع تقنية ثابتة، يمكن زيادة تكرار أو مجموعة أو اختيار رافعة أصعب. غيّر متغيرًا واحدًا في كل مرة. تعني تكراران احتياطيان التوقف حين تعتقد أنك تستطيع أداء تكرارين جيدين إضافيين. سلم الضغط مثال تعليمي، وليس اختبارًا موحدًا للجميع.')
content('قوة متاحة… ضمن نمط حياة نشط', ['تطوير القوة والتحمّل العضلي بحسب شدة التدريب.', 'تدريب التحكّم والتوازن عبر حركات مناسبة للمستوى.', 'معدات قليلة نسبيًا وإمكانية التدريب في أماكن متعددة.', 'للبالغين: تقوية العضلات يومين أو أكثر أسبوعيًا.', 'أضف 150–300 دقيقة من النشاط الهوائي المعتدل أسبوعيًا.'], 'صورة واقعية لنسخة ميسّرة من الضغط على قضيب مرتفع.', 'بطاقتا أرقام لتوصيات منظمة الصحة العالمية؛ لا تمثلان نتائج الكاليسثنيكس.', 'اربط سهولة الوصول بالاستمرارية، لا بفكرة أن التدريب مجاني أو مناسب تلقائيًا لكل شخص. العقلة الآمنة أو الحلقات قد تكون مفيدة، لكن يمكن البدء بحركات أرضية مناسبة. توصي منظمة الصحة العالمية البالغين بتقوية المجموعات العضلية الرئيسية يومين أو أكثر أسبوعيًا، مع 150 إلى 300 دقيقة هوائية معتدلة، أو 75 إلى 150 دقيقة شديدة، أو مزيج مكافئ. لا نفترض أن حصة قوة قصيرة تغطي الاحتياج الهوائي. الفوائد الصحية العامة تخص النشاط البدني، ولا ينبغي نسبتها حصريًا للكاليـسثنيكس.', [GUIDE, WHO, STUDY])
content('حدّد هدفك… ثم اختر أدواتك', ['القوة والتحمّل: تكرارات أنظف أو نسخة أصعب.', 'المهارة: تحكّم متدرج، لا تقليد الحركات الاستعراضية.', 'الاستمرارية: حصتان أساسيتان يمكن الالتزام بهما.', 'الأدوات: أرض ثابتة، عقلة موثوقة، شريط مقاومة اختياري.', 'مثال هدف: حصتان أسبوعيًا لمدة 8 أسابيع مع سجل أداء.'], 'صورة ضغط على قضبان مع ثلاث بطاقات أهداف.', 'ثلاث بطاقات هدف + شريط لصياغة هدف قابل للقياس (SMART).', 'ميّز بين هدف النتيجة وهدف السلوك. قد يرغب شخص في أول عقلة، لكن النتيجة تعتمد على نقطة البداية ووزن الجسم وخبرته؛ أما الالتزام بحصتين فيمكن تخطيطه مباشرة. يختار المبتدئ هدفًا أساسيًا واحدًا، مثل تحسين قوة الدفع مع بناء توازن بين الدفع والسحب والرجلين. يفضّل البدء بأدوات قليلة وموثوقة بدل شراء تجهيزات كثيرة. لا تستخدم أبوابًا أو طاولات أو قضبانًا غير مصممة لتحمل الجسم. هدف الأسابيع الثمانية مثال تنظيمي، وليس وعدًا بمهارة محددة.')
content('لماذا يتعثر التقدّم؟', ['تقليد مستوى متقدم ← اختيار نسخة قابلة للتحكّم.', 'دفع كثير وسحب قليل ← موازنة أنماط الحركة.', 'اختبارات قصوى متكررة ← تدريب دون استنزاف دائم.', 'غياب السجل والتعافي ← متابعة بسيطة وراحة منتظمة.'], 'مصفوفة تشخيصية بدل صورة مشتتة؛ أسهم تربط العائق بالاستجابة.', 'جدول من عمودين: عائق شائع / استجابة عملية.', 'هذه عوائق تعليمية شائعة وليست نتائج مسح إحصائي. اطلب من الجمهور تحديد العائق الأكثر قربًا من تجربته. ليست كل مشكلة بطءٍ في التحسن نقصًا في الجهد؛ فقد تكون النسخة أصعب من اللازم أو الحمل أكبر من التعافي. يُهمل السحب أحيانًا عند التدريب المنزلي لغياب تجهيز آمن، فلا نعوض ذلك بسحب من أثاث غير ثابت. لا حاجة إلى الوصول للعجز العضلي في كل مجموعة. سجّل التمرين ونسخته وتكراراته والتعب وأي ألم لتحديد تعديل معقول.')
content('خريطة الحركة: جسم كامل، لا عضلة واحدة', ['دفع أفقي: ضغط مائل → ضغط أرضي (Push-up).', 'سحب: تجديف بوزن الجسم → عقلة بمساعدة (Row / Pull-up).', 'دفع رأسي: ضغط بايك (Pike Push-up) بتدرج مناسب.', 'الرجلان: قرفصاء → اندفاع خلفي (Squat / Lunge).', 'الورك والجذع: جسر الأرداف وبلانك (Bridge / Plank).', 'مهارات لاحقة: وقوف على اليدين، L-sit، Front Lever، Muscle-up.'], 'جدول واضح يقابل أنماط الحركة بأمثلة وملاحظات تقنية.', 'مصفوفة حركات من خمسة صفوف مع شريط منفصل للمهارات المتقدمة.', 'غطِّ أنماط الحركة بدل جمع تمارين عشوائية. في الضغط حافظ على اتساق الجذع واختر ارتفاعًا يسهل التحكم. في السحب تجنب الاندفاع، واضبط الكتفين ضمن مدى مريح. في القرفصاء والاندفاع استخدم مدى يسمح بالاتزان والتحكم بالركبتين. لا تهمل الرجلين والورك بسبب التركيز على الجزء العلوي. يمكن زيادة صعوبة الرجلين تدريجيًا عبر العمل أحادي الطرف أو مقاومة إضافية. المهارات المتقدمة ليست جزءًا إلزاميًا من حصة المبتدئ؛ تحتاج إعدادًا خاصًا للرسغ والكتف وتقنية وتعافيًا كافيين.')
content('مساران تطبيقيان… لا وصفة واحدة', ['مبتدئ: ضغط مرتفع + سحب سهل + قرفصاء + بلانك قصير.', 'تقدّم: زد التكرارات أولًا؛ ثم قلّل ارتفاع سطح الضغط.', 'متوسط: أساسيات مستقرة + تدريب مهارة واحد قصير.', 'مثال مهارة: تحمّل الرسغ → بايك → وقوف مدعوم على اليدين.', 'حالتان افتراضيتان للتوضيح، وليستا نتائج تجربة.'], 'صورة النسخة الميسّرة من الضغط إلى جانب مساري التدريب.', 'مساران متوازيان: مستوى البداية / التدرّج / معيار القرار.', 'الحالة الأولى لشخص مبتدئ لا يستطيع ضغطًا أرضيًا نظيفًا؛ نرفع سطح الارتكاز إلى مستوى يسمح بتكرارات مضبوطة، ونضيف سحبًا فقط من جهاز ثابت. حين يبلغ أعلى النطاق بجودة في حصتين متتاليتين، يمكن خفض السطح قليلًا. الحالة الثانية لممارس يمتلك أساسًا جيدًا؛ يختار مهارة واحدة مثل الوقوف على اليدين، ويتعلم الدخول والخروج الآمنين مع مدرب عند الحاجة. تتقدم المهارة حين توجد سيطرة لا بمجرد مرور الأيام. لا تُنفذ محاولات انقلاب أو أسلوب حر دون تأهيل ومساحة آمنة.')
content('ما الذي تقوله البيانات فعلًا؟', ['دراسة عام 2017: 28 رجلًا غير مدرَّب، موزَّعون على مجموعتين.', 'التدخل التدريبي: 8 أسابيع؛ المقارنة قبل التدريب وبعده.', 'تحسّن اختبار الضغط في مجموعة التدريب: 16.4%.', 'تحسّن اختبار العقلة في مجموعة التدريب: 39.2%.', 'عينة صغيرة ومحدودة؛ لا تضمن النتيجة نفسها لكل فرد.'], 'مخطط أعمدة أفقي أصلي قابل للتحرير، مع بطاقات حجم العينة والمدة.', 'عمودان: نسبة تحسن أداء اختبار الضغط والعقلة؛ محور يبدأ من الصفر.', 'اعرض هذه الأرقام بوصفها نتائج دراسة محددة لا توقعات شخصية. شملت الدراسة 28 رجلًا غير مدرب موزعين على مجموعتي تدريب وضبط؛ هذا العدد ليس حجم مجموعة التدريب وحدها. استمر التدخل ثمانية أسابيع. تحسّن أداء اختباري الضغط والعقلة في مجموعة التدريب بنسبة 16.4 و39.2 بالمئة على الترتيب. تقيس النسب تغير الأداء في الاختبار ولا تعني زيادة الكتلة العضلية بهذه النسب. لم تظهر مجموعة الضبط فروقًا دالة في المتغيرات المقاسة. تحد العينة الصغيرة والجنس الواحد والمدة القصيرة من التعميم.', [STUDY, PDF])
content('تدرّب بذكاء: أمان وتعافٍ وتغذية', ['أحمِ الجسم بحركات خفيفة ومجموعات تمهيدية سهلة.', 'افحص ثبات المعدات؛ ارفع الحمل تدريجيًا.', 'اترك غالبًا 2–3 تكرارات احتياطية للمبتدئ.', 'نوم كافٍ، ماء، وطعام متوازن بمصادر بروتين منتظمة.', 'ألم حاد أو دوار أو ألم صدري؟ أوقف التمرين.'], 'صورة تدريب واقعية مع أربع بطاقات وقاية وشريط تنبيه.', 'أربع ركائز: الاستعداد / جودة الحركة / التعافي / التغذية.', 'الإحماء تحضير وليس ضمانًا لمنع الإصابات. ابدأ بنشاط خفيف وتحريك المفاصل المطلوبة ثم مجموعات أسهل من التمرين الأساسي. امنح العضلات المستهدفة عادة يوم راحة بين حصص البداية، وعدّل ذلك بحسب التعافي. احرص على كفاية الطعام والبروتين من مصادر متنوعة، فالمكملات ليست شرطًا، وتغير الدهون يعتمد على توازن الطاقة وعوامل أخرى. تعب العضلة يختلف عن الألم الحاد بالمفصل. أوقف النشاط عند الألم الحاد أو الدوار؛ ألم الصدر أو ضيق النفس غير المعتاد يستدعي تقييمًا عاجلًا. عند مرض مزمن أو إصابة قائمة، اطلب توجيهًا فرديًا من مختص.')
content('خطة انطلاق عملية: 8 أسابيع', ['حصتان لكامل الجسم أسبوعيًا، وبينهما يوم راحة على الأقل.', 'ضغط مائل: مجموعتان × 6–10 تكرارات.', 'سحب بوزن الجسم من جهاز ثابت: مجموعتان × 6–10.', 'قرفصاء + جسر الأرداف: مجموعتان × 8–12 لكل تمرين.', 'بلانك: مجموعتان × 15–25 ثانية مع تنفّس طبيعي.', 'راحة 60–120 ثانية؛ أطِلها عند الحاجة لجودة الأداء.'], 'جدول جرعات تدريبي مع خط زمني لأربع مراحل.', 'جدول تمارين + Timeline: تعلّم 1–2 / تثبيت 3–4 / تقدّم 5–6 / تقييم 7–8.', 'الخطة مثال عام لبالغ سليم مبتدئ وليست بروتوكول الدراسة السابقة. يمكن اختيار السبت والثلاثاء أو أي يومين يفصل بينهما يوم راحة على الأقل. ابدأ بإحماء من خمس إلى عشر دقائق تقريبًا. اختر نسخًا تترك تكرارين إلى ثلاثة احتياطيين؛ خفّض التكرارات أو اكتفِ بمجموعة واحدة إذا لزم. في أول أسبوعين تعلّم، ثم ثبّت التقنية في الثالث والرابع. في الخامس والسادس، إذا بلغت أعلى النطاق في كل المجموعات بجودة خلال حصتين، زد صعوبة متغير واحد وأعد التكرارات إلى الحد الأدنى. في السابع والثامن قارن الأداء في نفس الظروف. أضف المشي أو نشاطًا هوائيًا مناسبًا خارج حصص القوة، وخفّض الحمل عند التعب المستمر.')
content('النتائج المتوقعة: قِس الجودة أولًا', ['تحكّم أفضل وتكرارات أنظف مع الممارسة المنتظمة.', 'قوة وتحمّل أعلى محتملان؛ سرعة التحسن فردية.', 'تغيّر المظهر ليس مضمونًا ولا المقياس الوحيد.', 'تابع: الالتزام، النسخة، التكرارات، الراحة، والأعراض.', 'قارن نقطة البداية بالأسبوعين الرابع والثامن.'], 'لوحة متابعة فارغة مقصودة حتى لا تُقدَّم أرقام افتراضية كنتائج.', 'جدول متابعة: خط الأساس / الأسبوع 4 / الأسبوع 8، مع مؤشرات أداء.', 'اجعل التقييم قابلاً للمقارنة: نفس نسخة التمرين ومداه ومدة الراحة تقريبًا. إذا تغيّرت النسخة دوّن ذلك، لأن عشرة تكرارات مائلة لا تعادل عشرة أرضية. سجّل عدد الحصص المكتملة، وأفضل مجموعة سليمة دون إجبار على أقصى جهد، ومدة ثبات جيدة إن استُخدمت. يمكن للمبتدئ أن يلاحظ تحكمًا أفضل قبل تغير الشكل، ولا توجد مهلة مضمونة لأول عقلة أو مهارة. الخانات الفارغة نموذج لتعبئة بيانات حقيقية وليست بيانات مفقودة من دراسة. الألم المتكرر إشارة للمراجعة لا مؤشرًا على النجاح.')
content('الخلاصة: أتقن، وازن، ثم تقدّم', ['أتقن النسخة المناسبة قبل مطاردة الصعوبة.', 'وازن الدفع والسحب والرجلين والجذع.', 'ارفع الحمل تدريجيًا واحمِ وقت التعافي.', 'سجّل أداءك؛ عدّل الخطة وفق استجابتك.', 'ابدأ هذا الأسبوع بحصتين بسيطتين وآمنتين.'], 'صورة ضغط مع ثلاث كلمات كبيرة: إتقان / توازن / استمرارية.', 'مسار دائري مفاهيمي: تدريب ← تعافٍ ← قياس ← تعديل.', 'اختصر الرسالة في أن الكاليسثنيكس وسيلة مرنة لبناء قدرات الجسم وليست منافسة مع الآخرين. المهارة المتقدمة اختيار لاحق، والأساس هو تدريب متوازن تستطيع الاستمرار عليه. ليست هناك ضرورة للاختيار الحصري بين الكاليسثنيكس والأوزان؛ يمكن الجمع بينهما وفق الأهداف والأدوات. اطلب من كل مستمع اختيار تمرين دفع وسحب ورجلين وجذع مناسب، ثم موعد حصتين. ذكّر بأن جودة الحركة والتعافي والتدرج شروط عملية أهم من عدد الحركات المنشورة على وسائل التواصل.')
content('الأسئلة والنقاش', ['ما أول هدف واقعي يناسب مستواك الحالي؟', 'أي تمرين يحتاج إلى نسخة أسهل لديك؟', 'كيف ستوازن التدريب مع الراحة والنشاط الهوائي؟'], 'صورة هادئة من مساحة التدريب مع علامة استفهام هندسية كبيرة.', 'ثلاث بطاقات أسئلة؛ لا حاجة إلى مخطط بيانات.', 'امنح الجمهور دقيقة للتفكير قبل استقبال الأسئلة. من الأسئلة المتوقعة: هل يمكن بناء العضلات؟ نعم يمكن لتدريب المقاومة المناسب دعم ذلك مع التغذية والتعافي، ولا تكون كل الحركات كافية لكل هدف. هل يجب التدريب يوميًا؟ ليس مطلوبًا للمبتدئ؛ حصتان منظمتان بداية قابلة للاستمرار. ماذا أفعل إذا لم أستطع العقلة؟ اختر سحبًا أسهل من تجهيز آمن أو عقلة بمساعدة مناسبة. تجنب تشخيص آلام الحضور أو وصف تأهيل علاجي علنيًا، ووجّه الحالات الفردية إلى مختص.')
content('شكرًا لحسن المتابعة', ['قوّتك تُبنى… تكرارًا بعد تكرار.', 'منظمة الصحة العالمية: إرشادات النشاط البدني، 2020.', 'Thomas وزملاؤه: دراسة الكاليسثنيكس، 2017.', 'الصور: Pexels؛ الروابط التفصيلية في الملاحظات ودليل العرض.'], 'صورة ختامية متناسقة مع الغلاف ومساحة واضحة لكلمة شكرًا.', 'خاتمة تحريرية مع مراجع مختارة وروابط قابلة للنقر.', 'اشكر الحضور وادعهم للعودة إلى خطة البداية بدل محاولة تقليد المهارات الصعبة مباشرة. تضم ملاحظات الشرائح وروابط دليل العرض مصادر الأرقام والإرشادات والصور. المرجع البحثي هو The effects of a calisthenics training intervention on posture, strength and body composition، المنشور في Isokinetics and Exercise Science عام 2017، المجلد 25، الصفحات 215–222. خطة الأسابيع الثمانية صياغة تعليمية مستقلة وليست إعادة إنتاج للتدخل البحثي. راجع شروط استخدام الصور لدى المصدر عند إعادة توزيع العرض تجاريًا.', [GUIDE, WHO, STUDY, PDF])

prs=Presentation(); prs.slide_width=Inches(13.333); prs.slide_height=Inches(7.5)
prs.core_properties.title='الكاليسثنيكس | دليل شامل'
prs.core_properties.subject='تدريب وزن الجسم: الأساسيات والتدرج والسلامة'
prs.core_properties.author='[اسم مقدم العرض]'
prs.core_properties.keywords='Calisthenics, Arabic, Fitness, Bodyweight'
NAVY='101E2A'; CARD='1B2C39'; WHITE='F5F7F4'; INK='142633'; MUTED='AFC0C7'; TEAL='49D3BC'; ORANGE='EDAD66'; PALE='E5EDEA'; GRAY='536975'
FONT='Arial'
def rgb(h): return RGBColor.from_string(h)
def shape(sl,x,y,w,h,fill,kind=MSO_SHAPE.RECTANGLE,line=None):
    q=sl.shapes.add_shape(kind,Inches(x),Inches(y),Inches(w),Inches(h)); q.fill.solid(); q.fill.fore_color.rgb=rgb(fill)
    if line: q.line.color.rgb=rgb(line)
    else: q.line.fill.background()
    if kind==MSO_SHAPE.ROUNDED_RECTANGLE: q.adjustments[0]=0.12
    return q

def text(sl,x,y,w,h,txt,size=22,color=WHITE,bold=False,align=PP_ALIGN.RIGHT,rtl=True):
    q=sl.shapes.add_textbox(Inches(x), Inches(y), Inches(w), Inches(h)); tf=q.text_frame; tf.clear(); tf.word_wrap=True
    tf.margin_left=Pt(2); tf.margin_right=Pt(2); tf.margin_top=Pt(1); tf.margin_bottom=Pt(1)
    for j,line in enumerate(txt.split('\n')):
        p=tf.paragraphs[0] if j==0 else tf.add_paragraph(); p.alignment=align; p.space_after=Pt(4)
        p._p.get_or_add_pPr().set('rtl','1' if rtl else '0')
        r=p.add_run(); r.text=line; r.font.name=FONT; r.font.size=Pt(size); r.font.bold=bold; r.font.color.rgb=rgb(color)
        rp=r._r.get_or_add_rPr(); rp.set('lang','ar-DZ' if rtl else 'en-US')
        for tag in ['a:cs','a:ea']:
            e=OxmlElement(tag); e.set('typeface',FONT); rp.append(e)
    return q

def photo(sl,name,x,y,w,h):
    path=ROOT/'assets'/f'{name}.jpg'; im=Image.open(path); iw,ih=im.size
    q=sl.shapes.add_picture(str(path), Inches(x), Inches(y),width=Inches(w),height=Inches(h))
    box=w/h; ratio=iw/ih
    if ratio>box: crop=(1-box/ratio)/2; q.crop_left=crop; q.crop_right=crop
    else: crop=(1-ratio/box)/2; q.crop_top=crop; q.crop_bottom=crop
    return q

def base(i,light=False,section='أساسيات الحركة'):
    sl=prs.slides.add_slide(prs.slide_layouts[6]); sl.background.fill.solid(); sl.background.fill.fore_color.rgb=rgb(WHITE if light else NAVY)
    fg=INK if light else WHITE; muted=GRAY if light else MUTED
    shape(sl,12.53,.46,.15,.35,TEAL)
    text(sl,6,.46,6.3,.3,section,12,muted)
    text(sl,.6,.45,3,.3,'CALISTHENICS / FIELD GUIDE',10,muted,align=PP_ALIGN.LEFT,rtl=False)
    shape(sl,.6,7.02,12.1,.012,PALE if light else CARD)
    text(sl,10.7,7.13,2,.23,'قوة • تحكّم • استمرارية',9,muted)
    text(sl,.6,7.12,1.3,.23,f'{i:02d} / 15',10,muted,align=PP_ALIGN.LEFT,rtl=False)
    shape(sl,.6,7.44,12.1*i/15,.045,TEAL)
    if i not in [1,15]: text(sl,.7,1.03,11.9,.78,S[i-1]['title'],31,fg,True)
    return sl

def note(sl,i):
    d=S[i-1]
    sl.notes_slide.notes_text_frame.text=d['notes']+'\n\nالصورة أو الرسم: '+d['visual']+'\nالإنفوغرافيك: '+d['chart']+'\n\nالمصادر:\n'+'\n'.join(d['sources'])+'\n\nمصادر الصور: https://www.pexels.com/photo/10021267/ | https://www.pexels.com/photo/8455862/ | https://www.pexels.com/photo/4803700/'
    for p in sl.notes_slide.notes_text_frame.paragraphs: p._p.get_or_add_pPr().set('rtl','1')

def card(sl,x,y,w,h,num,title,body,light=False):
    shape(sl,x,y,w,h,PALE if light else CARD,MSO_SHAPE.ROUNDED_RECTANGLE)
    text(sl,x+w-.72,y+.2,.45,.4,num,15,GRAY if light else TEAL,True,PP_ALIGN.CENTER,False)
    text(sl,x+.2,y+.64,w-.4,.52,title,23,INK if light else WHITE,True)
    text(sl,x+.2,y+1.23,w-.4,h-1.3,body,18,GRAY if light else MUTED)

def footer_source(sl,label,light=False):
    text(sl,.7,6.66,11.9,.25,label,10,GRAY if light else MUTED)

def band(sl,txt,y=6.06,light=False):
    shape(sl,.7,y,11.9,.46,INK if light else TEAL,MSO_SHAPE.ROUNDED_RECTANGLE)
    text(sl,.9,y+.065,11.5,.34,txt,16,WHITE if light else INK,True)

