def table(sl,rows,x,y,widths,rowheight=.64,size=18):
    tbl=sl.shapes.add_table(len(rows),len(widths),Inches(x),Inches(y), Inches(sum(widths)), Inches(rowheight*len(rows))).table
    for j,w in enumerate(widths): tbl.columns[j].width=Inches(w)
    for i,row in enumerate(rows):
        tbl.rows[i].height=Inches(rowheight)
        for j,val in enumerate(row):
            c=tbl.cell(i,j); c.text=val; c.fill.solid(); c.fill.fore_color.rgb=rgb(INK if i==0 else (PALE if i%2 else 'EDF2EF'))
            c.margin_left=Inches(.13); c.margin_right=Inches(.13); c.margin_top=Inches(.06); c.margin_bottom=Inches(.04); c.vertical_anchor=MSO_ANCHOR.MIDDLE
            for p in c.text_frame.paragraphs:
                p.alignment=PP_ALIGN.RIGHT; p._p.get_or_add_pPr().set('rtl','1')
                for r in p.runs:
                    r.font.name=FONT; r.font.size=Pt(size); r.font.bold=i==0; r.font.color.rgb=rgb(WHITE if i==0 else INK)
                    e=OxmlElement('a:cs'); e.set('typeface',FONT); r._r.get_or_add_rPr().append(e)
    return tbl
